script:
frappe.ui.form.on("Item", {
    refresh: function(frm) {
        frm.add_custom_button("Update All Item Prices UOM", function() {
            frappe.call({
                method: "gormsolutions_mobile_app.custom_api.update_uom_price.update_all_item_prices_uom",
                callback: function(response) {
                    if (response.message) {
                        frappe.msgprint(__(response.message));
                    }
                }
            });
        }).addClass("btn-primary");
    }
});

frappe.ui.form.on("Purchase Invoice", {
    refresh: function(frm) {
        if (!frm.is_new() && frm.doc.status === "Return" && frm.doc.custom_suplier_return_status !== "Items Compensated") {
            frm.add_custom_button("Item Compansation", function() {
                frappe.new_doc("Purchase Return Management", {
                    supplier: frm.doc.supplier,
                    reference_purchase_invoice: frm.doc.name
                });
            }, "Create");
        }
    }
});

frappe.ui.form.on('Stock Reconciliation', {
    refresh: function(frm) {
        // Add a custom button
        frm.add_custom_button(__('Fetch Valuation Rate'), function() {
            // Fetch Valuation Rates and set them in the table
            if (frm.doc.items && frm.doc.items.length > 0) {
                // Get items without a valuation rate
                const missing_rates = frm.doc.items
                    .filter(item => !item.valuation_rate)
                    .map(item => item.item_code);

                if (missing_rates.length > 0) {
                    frappe.call({
                        method: 'frappe.client.get_list',
                        args: {
                            doctype: 'Item',
                            filters: {
                                name: ['in', missing_rates]
                            },
                            fields: ['name', 'valuation_rate']
                        },
                        callback: function(r) {
                            console.log(r)
                            if (r.message) {
                                const valuation_map = {};
                                r.message.forEach(item => {
                                    valuation_map[item.name] = item.valuation_rate;
                                });

                                let updated = false;
                                frm.doc.items.forEach(row => {
                                    if (!row.valuation_rate && valuation_map[row.item_code] !== undefined) {
                                        row.valuation_rate = valuation_map[row.item_code];
                                        updated = true;
                                    }
                                });

                                if (updated) {
                                    frm.refresh_field('items');
                                    frappe.msgprint(__('Missing Valuation Rates have been updated. Remember to save the document.'));
                                } else {
                                    frappe.msgprint(__('No missing Valuation Rates were found to update.'));
                                }
                            }
                        }
                    });
                } else {
                    frappe.msgprint(__('All items already have Valuation Rates set.'));
                }
            } else {
                frappe.msgprint(__('Please add items to the table first.'));
            }
        }, __('Actions'));
    }
});

frappe.ui.form.on('Item', {
    // Trigger when the Item document is saved or refreshed
    refresh: function(frm) {
        // Add a custom button to trigger the price creation
        frm.add_custom_button(__('Create Item Prices'), function() {
            create_item_prices_for_all_items();
        });
    }
});

// Function to create item prices for all items
function create_item_prices_for_all_items() {
    frappe.call({
        method: 'gormsolutions_mobile_app.custom_api.stock.material_transfer.create_item_prices_for_all_items',
        callback: function(response) {
            if (response.message) {
                frappe.msgprint(__('Item prices created successfully.'));
            } else {
                frappe.msgprint(__('No prices created.'));
            }
        },
        error: function(error) {
            frappe.msgprint(__('Error occurred while creating item prices.'));
        }
    });
}

frappe.ui.form.on('Item', {
    refresh: function(frm) {
        // Add a custom button to fetch items without prices
        frm.add_custom_button(__('Export Items Without Prices'), function() {
            frappe.call({
                method: 'gormsolutions_mobile_app.custom_api.stock.material_transfer.fetch_items_without_prices',
                callback: function(response) {
                    if (response.message) {
                        const file_url = response.message;
                        // Open the file URL to download
                        window.open(file_url, '_blank');
                    } else {
                        frappe.msgprint(__('No items without prices found.'));
                    }
                },
                error: function(error) {
                    frappe.msgprint(__('Error occurred while fetching items without prices.'));
                }
            });
        });
    }
});

frappe.ui.form.on("Item", {
    refresh(frm) {
        frm.add_custom_button("Update All Item Price UOMs", () => {
            frappe.call({
                method: "gormsolutions_mobile_app.custom_api.update_uom_price.update_all_item_prices_uoms",
                freeze: true,
                freeze_message: "Updating all item price UOMs...",
                callback: function(r) {
                    if (!r.exc) {
                        frappe.msgprint(r.message);
                    }
                }
            });
        });
    }
});
